<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>
const cities=@json($cities);const area=document.getElementById('area'),city=document.getElementById('city');function fillCities(){const old=city.dataset.old;city.innerHTML='<option value="">{{ $t['choose'] }}</option>';(cities[area.value]||[]).forEach(v=>{const o=document.createElement('option');o.value=v;o.textContent=v;if(v===old)o.selected=true;city.appendChild(o)})}area.addEventListener('change',fillCities);fillCities();
const sub={QUOTATION:'subQuote',SERVICE_REQUEST:'subMaintenance',CONSULTATION:'subConsult'};function syncType(){document.querySelectorAll('.subtypes').forEach(x=>x.classList.remove('show'));const intent=document.querySelector('input[name=request_intent]:checked');if(intent){document.getElementById(sub[intent.value]).classList.add('show');const visible=document.querySelector('#'+sub[intent.value]+' input[name=request_subtype]:checked')||document.querySelector('#'+sub[intent.value]+' input[name=request_subtype]');if(visible)visible.checked=true}syncEmergency()}document.querySelectorAll('input[name=request_intent]').forEach(x=>x.addEventListener('change',syncType));document.querySelectorAll('input[name=request_subtype]').forEach(x=>x.addEventListener('change',syncEmergency));function syncEmergency(){const v=document.querySelector('input[name=request_subtype]:checked')?.value;if(v==='URGENT_MAINTENANCE')document.getElementById('priority').value='EMERGENCY'}syncType();
const service=document.getElementById('service'),other=document.getElementById('otherField');function syncOther(){other.style.display=service.value==='Other'?'grid':'none'}service.addEventListener('change',syncOther);syncOther();
let lat=parseFloat(document.getElementById('latitude').value)||24.7136,lng=parseFloat(document.getElementById('longitude').value)||46.6753;const map=L.map('map').setView([lat,lng],11);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(map);const marker=L.marker([lat,lng],{draggable:true}).addTo(map);function setPos(a,b){lat=a;lng=b;marker.setLatLng([a,b]);document.getElementById('latitude').value=a.toFixed(7);document.getElementById('longitude').value=b.toFixed(7);document.getElementById('googleLink').href='https://www.google.com/maps?q='+a+','+b}setPos(lat,lng);marker.on('dragend',e=>{const p=e.target.getLatLng();setPos(p.lat,p.lng)});map.on('click',e=>setPos(e.latlng.lat,e.latlng.lng));document.getElementById('geo').addEventListener('click',()=>navigator.geolocation&&navigator.geolocation.getCurrentPosition(p=>{setPos(p.coords.latitude,p.coords.longitude);map.setView([p.coords.latitude,p.coords.longitude],15)}));
</script></body></html>